python3 - <<'PY'
for a in "abcd":
    f=f"archive_{a}/dftbp.cosmo"
    lines=open(f).read().splitlines()
    diel=None; fepsi=None; area_total=None
    for i,l in enumerate(lines):
        if "Dielectric energy" in l: diel=float(l.split("=")[1])
        s=l.strip()
        if s.startswith("fepsi"): fepsi=float(s.split("=")[1])
        if s.startswith("area"): area_total=float(s.split("=")[1])
    idx=[i for i,l in enumerate(lines) if l.strip()=="$segment_information"][0]
    end=[i for i,l in enumerate(lines) if l.strip()=="end" and i>idx][0]
    charge_sum=0.0; qphi=0.0; area_sum=0.0; n=0
    for l in lines[idx:end]:
        p=l.split()
        if len(p)<10: continue
        try:
            charge=float(p[5]); area=float(p[6]); pot=float(p[9])
        except: continue
        charge_sum+=charge; area_sum+=area; qphi+=charge*pot; n+=1
    print(f"{a}: nseg={n} fepsi={fepsi:.6f} area_hdr={area_total:.6f} seg_area_sum={area_sum:.6f} "
          f"sum_charge={charge_sum:.3e} sum(zeta*phi)={qphi:.10f} reported_diel={diel:.10f} ratio={diel/qphi:.5f}")
PY

