    Separator = "-"
    Suffix = ".skf"
  }
  HubbardDerivs { H = -0.1857
    O = -0.1575
  }
  ThirdOrderFull = Yes
  HCorrection = Damping { Exponent = 4.0 }
}
""" % extra
